parameters.jsCode:
const scan = $json;
const now = new Date().toISOString();

const scanned = Number(scan.scanned || 0);
const indexed = Number(scan.indexed || 0);
const updated = Number(scan.updated || 0);
const skipped = Number(scan.skipped || 0);
const missing = Number(scan.missing || 0);
const errors = Array.isArray(scan.errors) ? scan.errors : [];
const errorCount = errors.length;

const relevant = indexed + updated + errorCount + missing;
const hasRelevant = relevant > 0;

const items = [];

if (!hasRelevant) {
  items.push({
    json: {
      should_emit: false,
      scan_summary: { scanned, indexed, updated, skipped, missing, errors: errorCount },
    },
  });
  return items;
}

// Prefer aggregated event; individual only if changes <= 10 and no flood
const changedResults = (Array.isArray(scan.results) ? scan.results : []).filter((r) =>
  r && (r.status === 'indexed' || r.status === 'updated' || r.status === 'error' || r.status === 'unsupported')
);

if (changedResults.length > 0 && changedResults.length <= 10 && errorCount === 0 && missing === 0) {
  for (const r of changedResults) {
    const isUpdate = r.status === 'updated';
    items.push({
      json: {
        should_emit: true,
        source: 'obsidian_ingestion',
        severity: 'info',
        component: 'knowledge',
        event: isUpdate ? 'obsidian_note_updated' : 'obsidian_note_indexed',
        status: 'completed',
        timestamp: now,
        message: isUpdate ? 'Nota Obsidian atualizada no RAG.' : 'Nota Obsidian indexada no RAG.',
        requires_attention: false,
        suggested_action: null,
        details: {
          document_id: r.document_id ?? null,
          filename: r.filename ?? null,
          source_path: r.source_path ?? null,
          chunks: r.chunks ?? null,
          content_hash: r.content_hash ?? null,
          // NÃO incluir conteúdo/texto/embeddings
        },
        scan_summary: { scanned, indexed, updated, skipped, missing, errors: errorCount },
      },
    });
  }
} else {
  const sev = errorCount > 0 ? 'error' : 'info';
  items.push({
    json: {
      should_emit: true,
      source: 'obsidian_ingestion',
      severity: sev,
      component: 'knowledge',
      event: errorCount > 0 ? 'obsidian_ingestion_failed' : 'obsidian_sync_completed',
      status: errorCount > 0 ? 'failed' : 'completed',
      timestamp: now,
      message: errorCount > 0
        ? 'Falha parcial na sincronização Obsidian → RAG.'
        : 'Obsidian sincronizado com o RAG.',
      requires_attention: errorCount > 0,
      suggested_action: null,
      details: {
        scanned,
        indexed,
        updated,
        skipped,
        missing,
        errors: errorCount,
      },
      scan_summary: { scanned, indexed, updated, skipped, missing, errors: errorCount },
    },
  });
}

return items;

